CREATE TABLE IF NOT EXISTS public.capital_institution_icon (
    institution_id BIGINT PRIMARY KEY REFERENCES public.institution(id) ON DELETE CASCADE,
    png BYTEA NOT NULL CHECK (substring(png FROM 1 FOR 8) = decode('89504e470d0a1a0a', 'hex'))
);

